def wrap(text, width):
    lines = []
    paragraphs = text.split('\n')

    for paragraph in paragraphs:
        # Split into words (maximal runs of non-space characters)
        words = paragraph.split()

        # Process each word, splitting long words into chunks of width
        processed_words = []
        for word in words:
            while len(word) > width:
                processed_words.append(word[:width])
                word = word[width:]
            if word:
                processed_words.append(word)

        # Pack words greedily into lines
        if not processed_words:
            # Empty paragraph produces one empty line
            lines.append('')
        else:
            current_line = []
            current_length = 0

            for word in processed_words:
                word_len = len(word)
                # Calculate length if we add this word
                if current_line:
                    # Need a space before this word
                    new_length = current_length + 1 + word_len
                else:
                    # First word on the line
                    new_length = word_len

                if new_length <= width:
                    current_line.append(word)
                    current_length = new_length
                else:
                    # Start a new line
                    if current_line:
                        lines.append(' '.join(current_line))
                    current_line = [word]
                    current_length = word_len

            # Add the last line if it has words
            if current_line:
                lines.append(' '.join(current_line))

    return lines

